BEGIN;

DO $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.verificacion_entrevista_evidencias AS evidencia
    WHERE evidencia.motivo_clasificacion_id IN (
      SELECT motivo_id
      FROM (VALUES
        ('b0510000-0000-4000-8000-000000000001'::UUID),
        ('b0510000-0000-4000-8000-000000000002'::UUID),
        ('b0510000-0000-4000-8000-000000000003'::UUID),
        ('b0510000-0000-4000-8000-000000000004'::UUID),
        ('b0510000-0000-4000-8000-000000000005'::UUID),
        ('b0510000-0000-4000-8000-000000000006'::UUID),
        ('b0510000-0000-4000-8000-000000000007'::UUID),
        ('b0510000-0000-4000-8000-000000000008'::UUID),
        ('b0510000-0000-4000-8000-000000000009'::UUID),
        ('b0510000-0000-4000-8000-000000000010'::UUID),
        ('b0510000-0000-4000-8000-000000000011'::UUID),
        ('b0510000-0000-4000-8000-000000000012'::UUID),
        ('b0510000-0000-4000-8000-000000000013'::UUID),
        ('b0510000-0000-4000-8000-000000000014'::UUID),
        ('b0510000-0000-4000-8000-000000000015'::UUID)
      ) AS catalogo(motivo_id)
    )
  ) THEN
    RAISE EXCEPTION 'No se puede revertir: una evidencia ya utiliza un motivo del catálogo base';
  END IF;
END
$$;

DELETE FROM public.audit_log
WHERE tabla = 'motivos_clasificacion_evidencia'
  AND accion = 'MOT_EVI_BASE'
  AND registro_id IN (
    'b0510000-0000-4000-8000-000000000001'::UUID,
    'b0510000-0000-4000-8000-000000000002'::UUID,
    'b0510000-0000-4000-8000-000000000003'::UUID,
    'b0510000-0000-4000-8000-000000000004'::UUID,
    'b0510000-0000-4000-8000-000000000005'::UUID,
    'b0510000-0000-4000-8000-000000000006'::UUID,
    'b0510000-0000-4000-8000-000000000007'::UUID,
    'b0510000-0000-4000-8000-000000000008'::UUID,
    'b0510000-0000-4000-8000-000000000009'::UUID,
    'b0510000-0000-4000-8000-000000000010'::UUID,
    'b0510000-0000-4000-8000-000000000011'::UUID,
    'b0510000-0000-4000-8000-000000000012'::UUID,
    'b0510000-0000-4000-8000-000000000013'::UUID,
    'b0510000-0000-4000-8000-000000000014'::UUID,
    'b0510000-0000-4000-8000-000000000015'::UUID
  );

DELETE FROM public.motivos_clasificacion_evidencia
WHERE id IN (
  'b0510000-0000-4000-8000-000000000001'::UUID,
  'b0510000-0000-4000-8000-000000000002'::UUID,
  'b0510000-0000-4000-8000-000000000003'::UUID,
  'b0510000-0000-4000-8000-000000000004'::UUID,
  'b0510000-0000-4000-8000-000000000005'::UUID,
  'b0510000-0000-4000-8000-000000000006'::UUID,
  'b0510000-0000-4000-8000-000000000007'::UUID,
  'b0510000-0000-4000-8000-000000000008'::UUID,
  'b0510000-0000-4000-8000-000000000009'::UUID,
  'b0510000-0000-4000-8000-000000000010'::UUID,
  'b0510000-0000-4000-8000-000000000011'::UUID,
  'b0510000-0000-4000-8000-000000000012'::UUID,
  'b0510000-0000-4000-8000-000000000013'::UUID,
  'b0510000-0000-4000-8000-000000000014'::UUID,
  'b0510000-0000-4000-8000-000000000015'::UUID
);

COMMIT;
